function STEP(a, c):
  if c is empty: return empty
  lo <- min support of c;  hi <- max support of c
  out <- empty map
  for x from lo-1 to hi+1:
    v <- a*c[x-1] + (1-2a)*c[x] + a*c[x+1]   # absent cells read as 0
    if v != 0: out[x] <- v
  return out

function ITERATE(a, n, c):
  for i from 1 to n: c <- STEP(a, c)
  return c

